cd /tmp/checker && cat > scripts/erlang.py <<'EOF'
import math
def erlang_c_wait(n, a):
    """P_wait via Erlang B recursion, converted to Erlang C. Requires n > a."""
    if n <= a:
        return 1.0
    B = 1.0
    for k in range(1, n+1):
        B = a*B/(k + a*B)
    rho = a/n
    return B/(1 - rho*(1-B))
def erlang_c_wait_direct(n, a):
    # direct formula: (a^n/n! * n/(n-a)) / (sum_{k<n} a^k/k! + a^n/n! * n/(n-a))
    num = a**n/math.factorial(n) * n/(n-a)
    den = sum(a**k/math.factorial(k) for k in range(n)) + num
    return num/den
def sl(n, a, T, aht):
    if n <= a:
        return 0.0
    return 1 - erlang_c_wait(n, a)*math.exp(-(n-a)*T/aht)
def required(vol, aht, T, target, occmax=0.85, occ=True):
    a = vol/1200.0*aht
    if a == 0:
        return 0, a
    n = max(1, math.floor(a)+1)
    while True:
        ok = sl(n, a, T, aht) >= target - 1e-12
        if occ:
            ok = ok and (a/n <= occmax + 1e-12)
        if ok:
            return n, a
        n += 1
EOF
