import sys, csv, datetime as dt, collections, json
sys.path.insert(0,'/tmp/checker/scripts')
from erlang import required, sl, erlang_c_wait
IN='/tmp/checker/input/'
WEEK0 = dt.datetime(2027,3,15,0,0)  # UTC == local (GMT this week)
N=504
QUEUES=['priority','standard','email']
TGT={'priority':(90,30,0.90),'standard':(80,30,0.80),'email':(80,300,0.80)}
def iv_start(i): return WEEK0+dt.timedelta(minutes=20*i)
def fmt(t): return t.strftime('%Y-%m-%dT%H:%M:%SZ')
# demand
dem={}
for r in csv.DictReader(open(IN+'export_2027-W11.csv')):
    assert r['utc_offset']=='+00:00'
    end=dt.datetime.strptime(r['interval_end_local'],'%Y-%m-%d %H:%M')
    start=end-dt.timedelta(minutes=20)
    i=int((start-WEEK0).total_seconds()//1200)
    assert 0<=i<N, (r, i)
    dem[(r['queue'],i)]=(float(r['volume']), float(r['aht_sec']))
assert len(dem)==3*N
def local_hour(i): return (iv_start(i).hour, iv_start(i).minute)
OPER=[i for i in range(N) if 7*60 <= iv_start(i).hour*60+iv_start(i).minute < 21*60]
REQ={}; AR={}
for q in QUEUES:
    T,_,tgt=TGT[q]
    for i in range(N):
        v,aht=dem[(q,i)]
        n,a=required(v,aht,TGT[q][1],tgt,occ=True)
        nsl,_=required(v,aht,TGT[q][1],tgt,occ=False)
        REQ[(q,i)]=n; AR[(q,i)]=(a,nsl,aht)
# schedule
sched=list(csv.DictReader(open(IN+'schedule.csv')))
def p(s): return dt.datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ')
segs=[]
for r in sched:
    s=p(r['segment_start_utc']); e=p(r['segment_end_utc'])
    b=p(r['break_start_utc']) if r['break_start_utc'] else None
    segs.append(dict(agent=r['agent_id'],q=r['queue'],s=s,e=e,tpl=r['template_id'],idx=int(r['segment_idx']),
                     b=b,bm=int(r['break_minutes']),
                     ld=s.date()))
roster={}
for r in csv.DictReader(open(IN+'litware.csv')):
    roster[r['agent_id']]=dict(contract=r['contract'], skills=set(r['skills'].split(';')))
def ivs_in(seg):
    out=[]
    for i in range(N):
        t=iv_start(i)
        if t>=seg['s'] and t+dt.timedelta(minutes=20)<=seg['e']: out.append(i)
    return out
