    if g['e'].date()!=g['s'].date(): viol['midnight'].append(g)
# 2.2 split shifts
split_days=[]
for k,L in shifts.items():
    if len(L)>1:
        split_days.append(k)
        if roster[k[0]]['contract']!='PT': viol['split_contract'].extend(L)
# 2.5 email start
for g in segs:
    if g['q']=='email' and g['s'].time()<dt.time(9,0): viol['email_start'].append(g)
# 2.1 rest: consecutive shifts per agent
shift_objs={}
for k,L in shifts.items():
    shift_objs[k]=(min(g['s'] for g in L), max(g['e'] for g in L))
for a in roster:
    ks=sorted([k for k in shifts if k[0]==a], key=lambda k: shift_objs[k][0])
    for k1,k2 in zip(ks,ks[1:]):
        gap=shift_objs[k2][0]-shift_objs[k1][1]
        if gap < dt.timedelta(hours=11): viol['rest'].append((a,k1,k2,gap))
# 2.9 weekly hours and consecutive days
for a in roster:
    hrs=sum((g['e']-g['s']).total_seconds() for g in byagent[a])/3600
    lim=40 if roster[a]['contract']=='FT' else 24
    if hrs>lim: viol['weekly_hours'].append((a,hrs))
    days=sorted(set(k[1] for k in shifts if k[0]==a))
    run=1; best=1 if days else 0
    for d1,d2 in zip(days,days[1:]):
        run = run+1 if (d2-d1).days==1 else 1
        best=max(best,run)
    if best>5: viol['consecutive_days'].append((a,best))
# 2.3 breaks
break_info=[]
for k,L in shifts.items():
    tot=sum((g['e']-g['s']).total_seconds() for g in L)/3600
    s0=min(g['s'] for g in L)
    brks=[g for g in L if g['b'] is not None]
    if tot>=6:
        if len(brks)!=1: viol['break_count'].append((k,len(brks)))
        else:
            b=brks[0]['b']; q=brks[0]['q']
            off=(b-s0).total_seconds()/3600
            if not (2<=off<=5): viol['break_window'].append((k,b,off))
            # surplus window
            wstart=s0+2*HR; wend=s0+5*HR
            cands=[i for i in range(N) if wstart<=iv_start(i)<=wend]
            sur={i: gross[q][i]-REQ[(q,i)] for i in cands}
            mx=max(sur.values())
            bi=(b-WEEK0).total_seconds()//1200
            bi=int(bi)
            chosen=sur.get(bi)
            earliest=min(i for i in cands if sur[i]==mx)
            if chosen is None or chosen<mx: viol['break_not_max_surplus'].append((k,fmt(b),chosen,mx))
            elif iv_start(bi)!=iv_start(earliest): break_info.append(('tie-not-earliest',k,fmt(b),fmt(iv_start(earliest))))
            break_info.append(('ok_or_tie',chosen==mx))
    else:
        if brks: viol['break_under6h'].append((k,tot))
# 2.4 priority cover
pri_low=[i for i in OPER if gross['priority'][i]<2]
viol_pc=pri_low
if pri_low: viol['priority_cover']=[(fmt(iv_start(i)),gross['priority'][i]) for i in pri_low]
for key,val in viol.items():
    print(key, len(val))
    for x in val[:3]: print('   ', x if not isinstance(x,dict) else x)
print('split shift days', len(split_days), split_days)
print('break info sample', [b for b in break_info if b[0]!='ok_or_tie'][:10], 'ok/tie count', sum(1 for b in break_info if b[0]=='ok_or_tie' and b[1]))
print('priority low gross in OPER', [(fmt(iv_start(i)),gross['priority'][i]) for i in pri_low][:20], len(pri_low))
import pickle
pickle.dump(dict(gross=gross,net=net),open('/tmp/checker/cov.pkl','wb'))
EOF
