from model import *
res=pickle.load(open('/tmp/checker/res.pkl','rb'))
C=pickle.load(open('/tmp/checker/cov.pkl','rb')); gross=C['gross']
EXC=set(('email',i) for i in range(N) if dem[('email',i)][0]>0 and iv_start(i).time()<dt.time(9,0))
def need_ok(q,i): return res[q][i]['oper'] and (q,i) not in EXC
# 1) break flexibility: max-flow of breaks onto tied-max window intervals with capacity gross-req (no new shortfall)
segs_b=[g for g in segs if g['b'] is not None]
def tied(g):
    s0=min(x['s'] for x in segs if x['agent']==g['agent'] and x['ld']==g['ld'])
    cands=[i for i in range(N) if s0+dt.timedelta(hours=2)<=iv_start(i)<=s0+dt.timedelta(hours=5) and g['s']<=iv_start(i) and iv_start(i)+dt.timedelta(minutes=20)<=g['e']]
    sur={i: gross[g['q']][i]-REQ[(g['q'],i)] for i in cands}
    mx=max(sur.values()); return [i for i in cands if sur[i]==mx]
def window(g):
    s0=min(x['s'] for x in segs if x['agent']==g['agent'] and x['ld']==g['ld'])
    return [i for i in range(N) if s0+dt.timedelta(hours=2)<=iv_start(i)<=s0+dt.timedelta(hours=5) and g['s']<=iv_start(i) and iv_start(i)+dt.timedelta(minutes=20)<=g['e']]
def maxflow_assign(q, use_window):
    bl=[g for g in segs_b if g['q']==q]
    cap={i:max(0,gross[q][i]-REQ[(q,i)]) if need_ok(q,i) else 999 for i in range(N)}
    # for intervals where gross<req, placing a break there adds shortfall; they are short anyway -> cap 0 in flow sense
    load=collections.Counter(); assign={}
    # simple augmenting path bipartite b-matching
    match={}  # break idx -> interval
    cnt=collections.Counter()
    def try_b(bi, seen):
        g=bl[bi]
        opts = window(g) if use_window else tied(g)
        for i in opts:
            if i in seen: continue
            seen.add(i)
            if cnt[i] < cap[i]:
                cnt[i]+=1; match[bi]=i; return True
            # try to reassign someone currently at i
            for bj,ii in list(match.items()):
                if ii==i and try_b(bj, seen):
                    match[bi]=i; return True
        return False
    unplaced=[]
    for bi in range(len(bl)):
        if not try_b(bi,set()): unplaced.append(bi)
    return len(bl), len(unplaced), [fmt(iv_start(bl[bi]['b'] and ((bl[bi]['b']-WEEK0).total_seconds()//1200) and int((bl[bi]['b']-WEEK0).total_seconds()//1200))) for bi in unplaced]
for q in QUEUES:
    print(q, 'breaks placed without new shortfall (tied-max choice):', maxflow_assign(q, False)[:2], ' (window choice):', maxflow_assign(q, True)[:2])
